// How the built-ins are defined:
type MyPartial<T> = { [K in keyof T]?: T[K] };
type MyReadonly<T> = { readonly [K in keyof T]: T[K] };

// Your own:
type Flags<T> = { [K in keyof T]: boolean };
type FieldErrors<T> = { [K in keyof T]?: string };

interface ProfileForm { name: string; bio: string; age: number }

type Touched = Flags<ProfileForm>;       // { name: boolean; bio: boolean; age: boolean }
type Errors = FieldErrors<ProfileForm>;  // { name?: string; bio?: string; age?: string }
